INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129922, 'spa', 'Incendiar por juicio', 'En Isaías 27:4, Dios declara que prendería fuego a espinos y zarzas si se le opusieran. El español «los quemaré» enfatiza la acción en primera persona. Es Dios como guerrero, usando el fuego como arma para despejar lo que se opone a su viña (Israel). El verbo transmite tanto poder como totalidad: nada sobrevive al fuego divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129923, 'spa', 'Brillo o claridad intensa', 'Cantares 5:10 describe al amado como «radiante y rubicundo» (צַח וְאָדוֹם), destacando su apariencia deslumbrante. Isaías 18:4 habla de un «calor resplandeciente» durante la cosecha. Isaías 32:4 promete que las lenguas tartamudas «hablarán con claridad» (דַבֵּר צַחוֹת). Jeremías 4:11 menciona un «viento abrasador». El término abarca luminosidad visual, intensidad térmica y nitidez en el habla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129924, 'spa', 'Desecación extrema', 'Describe el estado de estar extremadamente seco o deshidratado, especialmente por falta de agua. Isaías 5:13 retrata la severidad del exilio: el pueblo «reseco de sed», mostrando una deshidratación total. Esta forma adjetival intensiva enfatiza lo extremo de la condición, no simplemente sediento, sino completamente marchito y agotado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129925, 'spa', 'Blancura deslumbrante', 'Aparecer con una blancura brillante y radiante. Lamentaciones 4:7 emplea este verbo para describir la tez de los nazareos antes del asedio: «más deslumbrantes que la leche», en paralelo con «más blancos que la nieve». El énfasis recae en un resplandor luminoso que sugiere piel rebosante de salud, en marcado contraste con su posterior estado demacrado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129926, 'spa', 'Peña desnuda', 'Ezequiel 24:7-8 emplea dos veces «peña desnuda» (צְחִיחַ סֶלַע) como el sitio donde se derramó la sangre de Jerusalén, no sobre tierra que la absorbiera, sino sobre roca expuesta que clama venganza. Ezequiel 26:4, 14 profetiza que Tiro quedará como «peña desnuda», lugar desolado donde pescadores tenderán sus redes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129927, 'spa', 'Tierra calcinada', 'Tierra abrasada y reseca hasta el punto de la desolación. El Salmo 68:6 describe a Dios haciendo habitar a los rebeldes «en tierra árida», sugiriendo un desierto estéril como realidad geográfica y juicio divino a la vez. Va más allá de la simple aridez: evoca un suelo quemado y endurecido, completamente inhóspito para la habitación humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129929, 'spa', 'Hedor nauseabundo', 'Olor fétido y nauseabundo, especialmente de materia orgánica en descomposición. Joel 2:20 describe el juicio de Dios sobre el ejército invasor: «subirá su pestilencia», en paralelo con «su hedor». La imagen evoca cadáveres pudriéndose al sol, una representación gráfica de la derrota total. También aparece en Sirácides 11:12 con el sentido de olor repugnante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129930, 'spa', 'Regiones abrasadas', 'Regiones calcinadas o devastadas por la sequía donde el agua está completamente ausente y el suelo se ha resecado. Isaías 58:11 contiene la promesa de Dios: «saciará tu alma en las sequedades», asegurando provisión incluso en los entornos más estériles. La raíz enfatiza no solo la aridez, sino la cualidad abrasada y quemada del terreno por el calor intenso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129931, 'spa', 'El sentido Piel de mofarse, escarnecer, ridiculizar o bromear —risa dirigida a a', 'El sentido Piel de mofarse, escarnecer, ridiculizar o bromear —risa dirigida a alguien con desprecio o desdén. El español burlarse/burlándose y el alemán Spott treiben resaltan el tono hostil. Ismael se burló de Isaac (Gn 21:9), Lot pareció como quien bromea al advertir a sus yernos (Gn 19:14), y la esposa de Potifar acusó dos veces a José de venir ''a burlarse'' de ellos (Gn 39:14, 17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129932, 'spa', 'El sentido básico Qal de reír, ya sea por gozo, sorpresa o incredulidad', 'El sentido básico Qal de reír, ya sea por gozo, sorpresa o incredulidad. El español rió/reirá y el alemán gelacht convergen en la risa espontánea. Sara se rió dentro de sí ante la promesa aparentemente imposible (Gn 18:12, 13, 15), Abraham cayó sobre su rostro y se rió (Gn 17:17), y la proclamación de que Dios ''me ha hecho reír'' (Gn 21:6) transforma la incredulidad en júbilo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129933, 'spa', 'El sentido Piel de jugar, divertirse, entretener o festejar —la risa como activi', 'El sentido Piel de jugar, divertirse, entretener o festejar —la risa como actividad festiva o amorosa en lugar de burla. El español jugar y el inglés ''amuse/play'' apuntan a una actividad recreativa. Isaac ''jugando'' (acariciando) con Rebeca reveló su relación a Abimelec (Gn 26:8), Israel se levantó ''a jugar'' en la juerga idolátrica ante el becerro de oro (Éx 32:6), y el cegado Sansón fue obligado a ''divertir'' a los filisteos (Jue 16:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129943, 'spa', 'Color leonado', 'Color gris rojizo o leonado que describe específicamente la lana en el comercio de lujo de Damasco (Ezequiel 27:18). El tono exacto es debatido: BDB sugiere «leonado» o «gris rojizo», mientras algunas traducciones optan por «blanca». El contexto de artículos comerciales finos apunta a un color distintivo y valioso de lana, posiblemente vinculado a una región específica o un método de procesamiento particular.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129944, 'spa', 'Nombre propio personal', 'Nombre propio que llevan tres individuos distintos en la Biblia hebrea. El padre del patriarca heteo aparece en los relatos de la compra de Macpela (Gn 23:8; 25:9), un simeonita en las listas de la migración a Egipto (Gn 46:10; Éx 6:15) y un judahita en la genealogía de Crónicas (1 Cr 4:7). Las traducciones transliteran de forma consistente: esp. ''Zohar'', fra. ''Zohar'', al. ''Zochar''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129945, 'spa', 'Color leonado', 'Describe una coloración leonada o clara en los asnos, sugiriendo animales de mayor valor. Jueces 5:10 se dirige a «los que montáis sobre asnas leonadas», aludiendo aparentemente a líderes o personas acaudaladas. El color específico indicaba estatus o calidad de cría. La raíz se vincula con tonos rojizo-grisáceos o pardos, distinguiendo a estos animales de los asnos comunes más oscuros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129946, 'spa', 'Nave marítima', 'Números 24:24 profetiza que naves de Quitim afligirán a Asiria y a Heber. Isaías 33:21 contrasta el río de Jerusalén, sin naves majestuosas, con la protección divina. Ezequiel 30:9 menciona mensajeros en naves que van a aterrorizar a Cus por la caída de Egipto. Daniel 11:30 predice que naves de Quitim se opondrán al rey del norte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129947, 'spa', 'Siba (צִיבָא / צִבָא), nombre propio del siervo de la casa de Saúl que se convir', 'Siba (צִיבָא / צִבָא), nombre propio del siervo de la casa de Saúl que se convirtió en administrador de las propiedades heredadas de Mefiboset. Las dieciséis ocurrencias se concentran en 2 Samuel 9, 16 y 19, donde Siba funciona como figura moralmente ambigua — siervo leal u oportunista interesado — cuyo testimonio contradictorio sobre Mefiboset crea uno de los episodios más humanamente realistas de la Historia de la Corte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129951, 'spa', 'Caza o presa —el animal, la carne o la pieza obtenida mediante la cacería', 'Caza o presa —el animal, la carne o la pieza obtenida mediante la cacería. Este sentido dominante (11 apariciones) se concentra en las narraciones de Isaac, Esaú y Jacob: Isaac envía a Esaú a ''cazar caza'' y ''hacerme un guiso sabroso'' (Gn 27:3-7), Jacob se disfraza y trae ''caza'' a su padre (Gn 27:25, 31, 33), y Esaú es descrito como conocedor de צַיִד (''hombre diestro en la caza'', Gn 25:27). Levítico 17:13 amplía el uso a cualquier animal o ave cazados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129952, 'spa', 'La caza como actividad u ocupación, describiendo la persecución misma en lugar d', 'La caza como actividad u ocupación, describiendo la persecución misma en lugar de lo capturado. Solo dos apariciones, ambas en Génesis 10:9, donde Nimrod es llamado gibbor tsayid liphnei YHWH (''poderoso cazador delante de Jehová''), repetido para énfasis. El español cazador, el francés chasseur y el alemán Jäger emplean sustantivos de agente o términos de actividad aquí, confirmando que los traductores reconocen la palabra como referida a la actividad de cazar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129959, 'spa', 'Provisión y sustento', 'Josué 9:14 relata que los líderes israelitas tomaron «de sus provisiones» para examinar la afirmación de los gabaonitas. Nehemías 13:15 condena el traer «alimento» a Jerusalén en sábado. Job 38:41 pregunta quién da «alimento» al cuervo cuando sus crías claman. El Salmo 132:15 promete bendecir abundantemente «su provisión», es decir, el sustento de Sion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129960, 'spa', 'Cazadores', 'Personas que cazan o atrapan animales, usado metafóricamente en Jeremías 16:16 para referirse a agentes divinos que persiguen al Israel disperso. Dios declara que enviará «muchos cazadores» a buscar a su pueblo en cada escondite. La imagen sugiere una persecución implacable y una búsqueda minuciosa que va más allá de las redes de los pescadores, empleando las habilidades de rastreo del cazador por montes y peñascos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129961, 'spa', 'Provisiones de viaje', 'Sustantivo que designa víveres o provisiones preparados para un viaje o expedición. José provee provisiones para el regreso de sus hermanos a Canaán (Gn 42:25; 45:21), Josué ordena a Israel preparar provisiones para cruzar el Jordán (Jos 1:11), y los gabaonitas muestran provisiones secas y mohosas como evidencia de su supuesto largo viaje (Jos 9:5). El árabe zādan y el coreano 양식 apuntan específicamente a provisiones de camino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129963, 'spa', 'Caza, presa', 'Sentido distinto referido a la caza o presa obtenida en la cacería, que aparece en Génesis 27:3 donde Isaac envía a Esaú al campo a cazar y preparar un guiso sabroso. El español ''caza'' y el alemán Wildbret (''carne de venado'') separan claramente este sentido de las meras provisiones de viaje. El cognado árabe ṣayd también significa ''cacería, presa'', reflejando la conexión con la raíz ṣūd (''cazar'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129967, 'spa', 'Nombre propio de la antigua ciudad costera fenicia al norte de Tiro, y por exten', 'Nombre propio de la antigua ciudad costera fenicia al norte de Tiro, y por extensión el hijo epónimo de Canaán (Gén 10:15 = 1 Cr 1:13). Las veintidós ocurrencias se refieren a la misma entidad geográfica, ya sea marcando el límite norte de Canaán (Gén 10:19), identificándola como ''la Gran Sidón'' (Jos 11:8; 19:28), o nombrándola como blanco de juicio profético junto a Tiro (Jer 25:22; Ezeq 28:21-22). El español ''Sidón'' preserva la transliteración antigua del hebreo צִידוֹן.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129973, 'spa', 'Sustantivo gentilicio masculino que designa a una persona o pueblo de la ciudad ', 'Sustantivo gentilicio masculino que designa a una persona o pueblo de la ciudad fenicia de Sidón, usado tanto en singular como en plural. En textos más antiguos (Deuteronomio, Josué, Jueces) parece designar a los fenicios en general — Deuteronomio 3:9 señala que los ''sidonios'' llaman al Hermón por otro nombre, y 1 Reyes 5:20 trata a los leñadores sidonios como efectivamente tirios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129982, 'spa', 'Forma femenina plural (צִדֹּנִיּוֹת) que designa a las mujeres de Sidón, disting', 'Forma femenina plural (צִדֹּנִיּוֹת) que designa a las mujeres de Sidón, distinguida por el sufijo plural femenino hebreo -וֹת. Aparece solo en 1 Reyes 11:1, donde enumera a las mujeres sidonias entre las esposas extranjeras de Salomón junto con moabitas, amonitas, edomitas e hititas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129985, 'spa', 'Sequedad o aridez como cualidad abstracta — la condición reseca y sin agua de la', 'Sequedad o aridez como cualidad abstracta — la condición reseca y sin agua de la tierra, usada adjetivalmente o como sustantivo abstracto. Diez ocurrencias describen paisajes caracterizados por la desecación: ''tierra seca y sedienta donde no hay agua'' (Sal 63:1), Dios transformando el desierto en estanques y ''la tierra seca en manantiales de aguas'' (Sal 107:35; Is 41:18), y el siervo del SEÑOR creciendo ''como raíz de tierra seca'' (Is 53:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129988, 'spa', 'Tierra seca, lugar árido — el referente geográfico concreto donde צִיָּה nombra ', 'Tierra seca, lugar árido — el referente geográfico concreto donde צִיָּה nombra un territorio real en vez de una cualidad. Cinco ocurrencias señalan territorios estériles específicos: el páramo donde los marginados malviven (Job 30:3), el desierto por el que Dios hizo brotar agua de la roca (Sal 78:17; 105:41), y el desierto que ''se alegrará'' con la redención venidera de Dios (Is 35:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129992, 'spa', 'Sequía como evento climático temporal — un período prolongado de grave escasez d', 'Sequía como evento climático temporal — un período prolongado de grave escasez de agua, más que la cualidad de la tierra o su ubicación. Una sola ocurrencia en Job 24:19 empareja צִיָּה con calor (חֹם) al describir cómo ''la sequía y el calor arrebatan las aguas de nieve,'' el ciclo estacional de escasez que aflige a los pobres.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129996, 'spa', 'marcador, monumento', 'Los tres contextos revelan propósitos diferentes para los marcadores: memorial (lápida), navegacional (señales de camino), e identificatorio (marcadores de huesos). Los ''marcadores de camino'' de Jeremías guían a los exiliados que regresan, mientras que los marcadores de Ezequiel señalan ubicaciones que necesitan entierro. La diversidad en traducciones (español ''monumento/señal'', francés debate entre ''Sion'' y ''marcador'') refleja el rango funcional de la palabra. Lo que unifica es la visibilidad y función comunicativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129997, 'spa', 'Sion (nombre propio)', 'El nombre propio Sion, originalmente la cresta fortificada conquistada por David (2 S 5:7; 1 Cr 11:5), extendido luego al monte del Templo y a toda la ciudad de Jerusalén. En el uso profético y poético se convierte en símbolo teológico del lugar de morada escogido por Dios y, por metonimia, de su pueblo pactual, como cuando Isaías habla de la ''hija de Sion'' (Is 1:8). Las lenguas de traducción transliteran consistentemente el nombre con variantes como Sión, Tsiyon o Tzión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130013, 'spa', 'Ziha (nombre personal)', 'Las tres referencias abarcan Esdras 2:43, Nehemías 7:46 (listas paralelas de retornados), y Nehemías 11:21 (estructura de liderazgo). Los ''hijos de Ziha'' formaron una unidad familiar reconocida entre los Netinim, con Ziha mismo sirviendo como supervisor. Las formas entre corchetes en alemán y francés reflejan las variaciones morfológicas (con o sin conjunciones, diferencias menores de ortografía), pero todos identifican el mismo nombre personal vinculado al servicio del templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130014, 'spa', 'Bestia del desierto', 'Bestia salvaje o criatura del desierto que habita ruinas desoladas. Isaías 13:21 y 34:14 emparejan a los tsiyyim con los iyyim (criaturas aullantes) para representar la devastación total. Jeremías 50:39 profetiza que Babilonia será hogar de estos animales. El español ''bestias del desierto'' refleja la lectura zoológica, aunque la especie exacta sigue siendo debatida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130016, 'spa', 'Morador del desierto', 'Moradores del desierto o habitantes del yermo, posiblemente designando a pueblos nómadas o figuras ambiguamente humanas. El Salmo 72:9 vislumbra a los ''del desierto'' postrándose ante el rey, y el Salmo 74:14 habla del Leviatán dado como alimento a un ''pueblo del desierto''. El español ''moradores del desierto'' marca el cambio del referente animal al humano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130019, 'spa', 'Argolla o cepo', 'Dispositivo de sujeción, probablemente un collar o picota usada para castigar y humillar públicamente a los prisioneros. Jeremías 29:26 describe la autoridad del oficial del templo para poner a cualquier «loco que profetice» en el cepo y la argolla, mostrando que se empleaba en conjunto con otros medios de inmovilización para máxima restricción y escarnio. El aparato limitaba el movimiento y marcaba al portador como condenado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130020, 'spa', 'Topónimo en Judá', 'Nombre de una ciudad en el territorio tribal de Judá (Josué 15:54), ubicada en la región montañosa. Las fuentes geográficas la identifican con la actual Ṣâʿîr, cerca de Hebrón. El nombre aparece en las listas territoriales que definen la herencia de Judá, como uno de los muchos asentamientos en las tierras altas centrales que conformaban el núcleo del territorio de esta tribu.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130021, 'spa', 'Una flor o capullo, ya sea en sentido literal o figurado', 'Una flor o capullo, ya sea en sentido literal o figurado. Números 17:8 describe la vara de Aarón produciendo flores como señal divina. Isaías 40:6-8 y Salmo 103:15 emplean la flor que se marchita como metáfora de la transitoriedad humana: ''como la flor del campo, así florece''. Job 14:2 compara igualmente la vida humana a una flor que brota y se marchita. En 1 Reyes 6:18-35, diseños florales tallados (צִצִים) adornan el templo de Salomón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130023, 'spa', 'La placa o roseta de oro fijada en la parte frontal del turbante del sumo sacerd', 'La placa o roseta de oro fijada en la parte frontal del turbante del sumo sacerdote. Éxodo 28:36 ordena hacer una placa de oro puro grabada con ''Santo a Jehová'', y Éxodo 39:30 y Levítico 8:9 registran su fabricación y colocación. El árabe safihata (''una placa/lámina de metal'') distingue claramente este sentido del floral. El español ''lámina'' y ''placa'' también reflejan un término de metalurgia. Este objeto sacerdotal simboliza la consagración del sumo sacerdote al servicio de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130028, 'spa', 'Alas', 'Alas o plumas de ala, empleadas en la orden metafórica «dad alas a Moab» (Jeremías 48:9), que significa permitir que Moab huya con rapidez. Los cognados arameos respaldan la interpretación de «alas», acorde con el contexto de escape urgente ante el juicio. Aunque algunos estudiosos proponen lecturas alternativas («señal» o «plumas»), la imagen de las alas capta mejor la urgencia de la huida ante la destrucción divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130029, 'spa', 'Paso de montaña', 'Nombre de un paso o cuesta cerca del mar Muerto (2 Crónicas 20:16), por donde las fuerzas invasoras subían hacia Judá desde el oriente. Los estudiosos modernos lo sitúan en el terreno al norte de En-gadi. El nombre señala una ruta estratégica a través del desierto, utilizada por ejércitos que ascendían desde la cuenca del mar Muerto hacia las tierras altas de Judá.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130030, 'spa', 'Flor efímera', 'Flor o capullo usado metafóricamente en Isaías 28:4 para representar la gloria pasajera de Efraín. El profeta describe el esplendor del reino del norte como «la flor marchita de su hermosa gloria», subrayando lo transitorio. La imagen floral destaca la vulnerabilidad: lo que florece con brillo pronto se mustia, tal como el orgullo de Israel se marchitaría ante la invasión asiria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130031, 'spa', 'Fleco y mechón', 'Números 15:38 (dos veces) y 15:39 establecen el mandato de hacer flecos en los bordes de las vestiduras con un cordón azul, como recordatorio visual para obedecer los mandamientos de Dios. Ezequiel 8:3 describe cómo el profeta fue agarrado por un «mechón de cabello» (צִיצִת רֹאשִׁי) y levantado en una visión, mostrando el mismo término aplicado a algo que cuelga prominentemente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130032, 'spa', 'Enviado, mensajero, embajador', 'Un enviado, mensajero o embajador oficial despachado en misión de importancia diplomática o profética. Las traducciones al español alternan entre ''embajadores'' y ''mensajero'', reflejando el doble registro del término: embajador formal y mensajero general. La mayoría de las apariciones se encuentran en oráculos proféticos (Jer 49:14 = Abd 1, donde el SEÑOR envía un emisario entre las naciones; Isa 18:2, mensajeros desde Cus; Isa 57:9, enviados de Israel a aliados paganos) y en la literatura sapiencial (Prov 13:17; 25:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130038, 'spa', 'Gozne de puerta', 'Mecanismo de pivote o bisagra que permite a una puerta abrirse y cerrarse. Proverbios 26:14 emplea una imagen inolvidable: «Como la puerta gira sobre sus goznes, así el perezoso se vuelve en su cama». La comparación resalta la rotación sin propósito: la puerta se mueve pero permanece en su marco, igual que el holgazán se da vuelta sin levantarse. El gozne se convierte en símbolo de movimiento sin avance.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130039, 'spa', 'Dolores convulsivos', 'Dolores agudos o punzadas convulsivas, generalmente comparados con los dolores de parto o derivados de ellos. El sentido literal aparece en 1 S 4:19, mientras que Isaías lo despliega como símil del terror existencial (Is 13:8 junto a ''dolores de parto'', Is 21:3 describiendo el pavor visceral del profeta). Daniel 10:16 lo extiende a la angustia visionaria. La evidencia multilingue converge en vocabulario de dolor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130041, 'spa', 'Tomar provisiones', 'Proveerse de alimento o tomar bastimentos para un viaje. Josué 9:4, 12 emplea este verbo en hitpael para describir la artimaña de los gabaonitas: «este pan nuestro lo tomamos como provisión» al partir de su tierra, supuestamente semanas antes. El verbo enfatiza el acto de preparar comida para el viaje. Variantes textuales sugieren que el versículo 4 también debería leerse con este verbo, manteniendo coherencia con el contexto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130042, 'spa', 'La sombra como figura de lo efímero y la fragilidad humana', 'La sombra como figura de lo efímero y la fragilidad humana. Siempre en símiles — ''como una sombra'' (כְּצֵל) — este sentido impregna la poesía sapiencial y de lamento: los días declinan como una sombra (Sal 102:11), el hombre huye como una sombra (Job 14:2) y la riqueza terrenal resulta tan insustancial como la sombra que se desvanece (1 Cr 29:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130043, 'spa', 'El uso bíblico predominante', 'El uso bíblico predominante: sombra como abrigo protector o refugio. El salmista clama por seguridad ''a la sombra de tus alas'' (Sal 17:8; 57:1), mientras que Ezequiel y Oseas lo aplican a la sombra cobijadora de grandes árboles que representan reinos. Las traducciones en múltiples lenguas confirman que la metáfora es universalmente reconocida como protección.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130045, 'spa', 'El sentido concreto y físico', 'El sentido concreto y físico: la mancha oscura que se forma cuando un objeto bloquea la luz solar. Especialmente importante en la narrativa de Ezequías (2 R 20:9-11), donde la sombra en los peldaños de Acaz retrocede diez grados como señal divina. También aparece en la fábula de Jotam (Jue 9:36) y en descripciones de la sombra del follaje (Job 40:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130066, 'spa', 'Asar carne', 'Primer Samuel presenta el asado en contexto sacerdotal—el método preferido de cocción en el santuario. El retrato irónico de Isaías muestra a alguien asando carne (''aso carne, como'') con combustible que también sirve su idolatría. El contraste con hervir (Éxodo 12:9: ''no hervido en agua'') marca el asado como el método prescrito para comidas sagradas. La consistencia translingüística (''asa'', ''roast'', ''rôti'') confirma esta acción culinaria con significado ritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130067, 'spa', 'Esposa de Lamec', 'Génesis 4:19 introduce a Zila como esposa de Lamec; los versículos 22-23 la nombran nuevamente en contextos genealógicos y narrativos. Ella representa parte del linaje cainita que desarrolla la civilización temprana (metalurgia, música) pero también muestra violencia y orgullo. La evidencia multilingüe muestra variaciones menores de ortografía (con/sin conjunciones: ''Y-Zila'', ''Zila'') pero reconocimiento uniforme de este como nombre femenino de la línea de Caín.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130069, 'spa', 'Irrumpir poderosamente (Espíritu)', 'El Espíritu de YHWH irrumpiendo o viniendo con poder sobre una persona, capacitándola para acciones heroicas o proféticas. Este es el uso dominante y teológicamente más significativo, atestiguado ocho veces en Jueces y 1 Samuel. El español ''vino con poder'' y el francés ''se precipita'' transmiten el descenso repentino y abrumador. Pasajes clave: Jue 14:6, 19 (Sansón), Jue 15:14 (Sansón en Lehi), 1 S 10:6, 10 (Saúl).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130073, 'spa', 'Estallar, arder (fuego)', 'Fuego o ira que estalla o arde repentinamente, una extensión metafórica de la raíz que denota irrupción. Amós 5:6 advierte: ''para que no se lance como fuego sobre la casa de José.'' El español ''se lance'' y el inglés ''breaks out'' transmiten la erupción súbita, mientras que la traducción francesa ''prosperer'' (prosperar) parece confundir este verbo con el homónimo H6743b (tener éxito/prosperar).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130074, 'spa', 'Cruzar velozmente', 'Movimiento físico veloz a través del terreno, como soldados que cruzan o atraviesan un espacio rápidamente. 2 Samuel 19:17 describe a los hombres de David cruzando presurosos el Jordán para escoltar al rey. El español ''cruzaron'' y el francés ''se precipita'' confirman un desplazamiento rápido y decidido, distinto del empoderamiento divino o la erupción ígnea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130075, 'spa', 'Prosperar, tener éxito o florecer de manera intransitiva — el sujeto mismo exper', 'Prosperar, tener éxito o florecer de manera intransitiva — el sujeto mismo experimenta el éxito. José ''prosperó'' en casa de Potifar (Gn 39:2), los guerreros preguntan si su ''camino prosperará'' (Jue 18:5), y el propósito de Dios ''prospera'' a través del Siervo (Is 53:10). Es el sentido más frecuente, que atraviesa la literatura narrativa, sapiencial y profética.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130083, 'spa', 'Hacer prosperar u otorgar éxito — el Hifil causativo donde Dios o un agente supe', 'Hacer prosperar u otorgar éxito — el Hifil causativo donde Dios o un agente superior produce la prosperidad de otro. El siervo de Abraham acredita repetidamente a Dios: ''Yahvé ha prosperado mi camino'' (Gn 24:56). El éxito de José en Egipto se enmarca de la misma manera: ''Yahvé hacía prosperar todo lo que él hacía'' (Gn 39:3). La agencia teológica es central.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130084, 'spa', 'Ser apto, útil o servir para un propósito — un sentido Qal distinto que denota i', 'Ser apto, útil o servir para un propósito — un sentido Qal distinto que denota idoneidad práctica más que prosperidad. El cinturón arruinado de Jeremías ''no servía para nada'' (Jer 13:7, 10), y Ezequiel pregunta si la rama de vid quemada ''sirve para alguna obra'' (Ez 15:4). El español ''¿Servirá?'' capta la cualidad pragmática y evaluativa que distingue este sentido del mero éxito.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130108, 'spa', 'Prosperar y promover', 'Esdras 5:8 reporta que la obra del templo «prospera» (מַצְלַח) en manos de los constructores. Esdras 6:14 dice que los ancianos «prosperaron en la edificación» (וּמַצְלְחִין) gracias al aliento profético y el respaldo persa. Daniel 3:30 indica que el rey «promovió» (הַצְלַח) a los tres amigos. Daniel 6:28 declara que Daniel «prosperó» bajo Darío y Ciro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130109, 'spa', 'Recipiente de cocina', 'Olla o sartén utilizada para cocinar, mencionada en los preparativos de la Pascua en 2 Crónicas 35:13. El texto describe la cocción de las ofrendas sagradas «en ollas, en calderos y en sartenes», indicando diferentes tamaños o tipos de recipientes. La forma plural sugiere que eran parte del equipamiento habitual para la preparación de alimentos en gran cantidad durante las celebraciones festivas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130110, 'spa', 'Vasija pequeña', 'Vasija o recipiente pequeño, mencionado específicamente en el milagro de Eliseo en Jericó (2 Reyes 2:20). El profeta pide «una vasija nueva» para depositar sal y purificar el manantial envenenado. La novedad del recipiente subraya la pureza ritual necesaria para el milagro. Era un objeto de tamaño modesto, fácilmente transportable, que servía como instrumento de la sanidad divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130111, 'spa', 'Plato doméstico', 'El plato aparece en dos contextos: juicio profético (2 Reyes) y literatura sapiencial (Proverbios). En el oráculo de juicio, el plato se convierte en metáfora de destrucción total—limpiado y volteado. En los proverbios, es la vasija de comida del perezoso, resaltando la indolencia absurda. El acuerdo multilingüe sobre ''plato/dish/plat'' confirma el artículo doméstico básico, ya sea usado literal o figurativamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130112, 'spa', 'Carne asada al fuego', 'Éxodo da la prescripción ritual: ''asado al fuego'' (no hervido), definiendo la observancia pascual apropiada. El uso satírico de Isaías juega con la realidad doméstica ordinaria de asar carne mientras condena el absurdo de adorar madera de la misma fuente de combustible. Las representaciones multilingües distinguen ''asado de [fuego]'' (adjetival, Éxodo) de ''un asado'' (nominal, Isaías). El término ancla tanto la práctica culinaria como la obediencia ritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130113, 'spa', 'Hundirse en el agua', 'Hundirse o quedar sumergido en el agua, usado para describir al ejército del faraón en Éxodo 15:10: «se hundieron como plomo en las aguas impetuosas». El verbo capta la caída veloz e irreversible de las fuerzas egipcias cuando el mar se cerró sobre ellas. El símil del plomo subraya peso y rapidez: sin lucha ni flotación, solo inmersión y muerte instantánea. Esta imagen se convirtió en símbolo central de la liberación divina de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130114, 'spa', 'Retumbar y temblar', '1 Samuel 3:11, 2 Reyes 21:12 y Jeremías 19:3 emplean la frase «le retumbarán ambos oídos», imagen vívida de noticias tan impactantes que los oídos zumban. Habacuc 3:16 describe la reacción física del profeta ante la teofanía divina: «temblaron mis labios» (צָֽלְלוּ). Las traducciones existentes retumbarán y zumbarán reflejan bien esta resonancia aguda y perturbadora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130116, 'spa', 'Sombra y refugio', 'Job 40:22 describe los lotos proporcionando «sombra» a Behemot. Cantares 2:17 y 4:6 hablan de «hasta que sople el día y huyan las sombras», refiriéndose a las sombras vespertinas que desaparecerán al amanecer. Jeremías 6:4 advierte que «las sombras de la tarde se alargan», señalando que el tiempo se agota. El término abarca tanto la sombra literal como la metáfora temporal de lo efímero.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130117, 'spa', 'Nombre propio femenino', 'Nombre de mujer que aparece en la genealogía de Judá (1 Crónicas 4:3). Su significado es incierto, pero podría relacionarse con «sombra» y «volverse», quizá «dame sombra, tú que te vuelves hacia mí». Las lecturas muy divergentes de la Septuaginta reflejan la dificultad escribal con este texto. Su presencia como nombre femenino poco común en genealogías patriarcales indica que tuvo cierta importancia en la memoria de su familia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130118, 'spa', 'Representación tallada, fundida o moldeada de una deidad u objeto — un ídolo o i', 'Representación tallada, fundida o moldeada de una deidad u objeto — un ídolo o imagen de culto. Usada para las réplicas doradas de tumores en 1 Samuel 6:5, las imágenes destruidas de Baal en 2 Reyes 11:18, y las imágenes prohibidas con forma masculina de Ezequiel 16:17. Las traducciones multilingües convergen en ''ídolo/estatua/imagen,'' confirmando el referente concreto y físico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130119, 'spa', 'La semejanza o forma esencial en la que Dios creó a la humanidad y mediante la c', 'La semejanza o forma esencial en la que Dios creó a la humanidad y mediante la cual un padre engendra a su hijo (Gn 1:26-27, 5:3, 9:6). Este es el sentido fundacional de la imago Dei. Cada gran tradición de traducción lo rinde con términos para ''semejanza'' o ''imagen.'' Génesis 9:6 fundamenta la santidad de la vida humana en esta imagen divina compartida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130127, 'spa', 'Fantasma, sombra o apariencia insustancial — la cualidad efímera de la existenci', 'Fantasma, sombra o apariencia insustancial — la cualidad efímera de la existencia humana. En el Salmo 39:6 una persona camina ''como צֶלֶם,'' y en el Salmo 73:20 Dios desprecia la imagen del impío al despertar. Una llamativa extensión metafórica desde los sentidos concretos de ''imagen.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130129, 'spa', 'Imagen física, estatua o semejanza — una forma visible que representa algo o a a', 'Imagen física, estatua o semejanza — una forma visible que representa algo o a alguien. En Daniel 2:31-35 se refiere repetidamente a la gran estatua compuesta del sueño de Nabucodonosor, hecha de metales sucesivos que simbolizan imperios mundiales. Daniel 3:1-18 la usa para la imagen de oro que el rey erigió en la llanura de Dura. En Génesis (1:26-27; 5:3; 9:6), la misma raíz denota la imagen divina en la humanidad. Daniel 3:19 la emplea excepcionalmente para una expresión facial (''la imagen de su rostro cambió'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130135, 'spa', 'Guerrero de David', 'Nombre personal de uno de los treinta guerreros de élite de David (2 Samuel 23:28). El pasaje paralelo de 1 Crónicas 11:29 lo identifica como Ilai, lo cual posiblemente refleja tradiciones distintas o variantes del nombre de este combatiente. Aparece entre los héroes que formaron el núcleo del liderazgo militar de David, cada uno reconocido por actos individuales de valor en los inicios de la monarquía israelita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130136, 'spa', 'Oscuridad intensamente profunda entendida como la sombra más densa concebible, a', 'Oscuridad intensamente profunda entendida como la sombra más densa concebible, a menudo en paralelo con חֹשֶׁךְ (''oscuridad'') y לַיְלָה (''noche''). Tradicionalmente analizada como ''sombra de muerte'' (צֵל + מָוֶת), dando la imagen inolvidable del Salmo 23:4. En Job caracteriza el Seol y la desesperación más extrema (Job 10:21-22; 12:22). Amós 5:8 y Jeremías 13:16 la usan para la oscuridad cósmica o amenazada que solo Dios puede transformar en luz de la mañana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130144, 'spa', 'Zalmuna (nombre propio)', 'Uno de los dos reyes madianitas (siempre emparejado con Zeba) perseguidos al otro lado del Jordán, capturados y ejecutados por Gedeón como venganza de sangre por sus hermanos muertos en Tabor (Jue 8:5-21). El Salmo 83:12 invoca a Zeba y Zalmuna como enemigos derrotados paradigmáticos. Las doce ocurrencias se refieren al mismo individuo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130147, 'spa', 'Cojear y renquear', 'Génesis 32:31 señala que Jacob iba «cojeando de su cadera» tras la lucha en Peniel, origen de la práctica alimentaria de Israel. Miqueas 4:6 y 4:7 emplean el participio femenino «la coja» (הַצֹּלֵעָה) para describir a la nación exiliada que Dios reunirá. Sofonías 3:19 promete igualmente salvar «a la coja» y recoger a la dispersa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130148, 'spa', 'Tropiezo/Calamidad figurativa', 'Los tres usos son figurativos: vulnerabilidad personal en Salmos, la ruina inminente del malvado en Job, y los enemigos de Jeremías esperando su fracaso. El español ''cojear'' y ''caída'' capturan las dimensiones física y metafórica. Algunas traducciones luchan con la imagen (el francés ''sombra'' pierde el punto), pero la mayoría reconoce el tropiezo como el momento de debilidad cuando el desastre ataca.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130150, 'spa', 'El lado o flanco de un objeto construido, sentido dominante con 19 apariciones', 'El lado o flanco de un objeto construido, sentido dominante con 19 apariciones. Abarca los lados del arca de la alianza (Éx 25:12-14), los lados del altar (Éx 27:7), las paredes laterales del tabernáculo (Éx 26:20, 26-27, 35; 36:25-32) y elementos estructurales similares. El vocablo funciona como término espacial-direccional que indica el aspecto lateral del mobiliario y los edificios sagrados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130153, 'spa', 'Tablones, tablas u hojas de puerta, con 4 apariciones en 1 Reyes 6', 'Tablones, tablas u hojas de puerta, con 4 apariciones en 1 Reyes 6:15-16, 34, que describen las tablas de cedro y ciprés que revisten las paredes y el piso interiores del templo de Salomón, y las dos hojas de las puertas de madera de olivo. BDB las conecta con ''costillas de cedro y abeto'', sugiriendo que los tablones planos se percibían como alargados y delgados al modo de costillas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130154, 'spa', 'Cámaras laterales o aposentos del templo, con 14 apariciones concentradas en las', 'Cámaras laterales o aposentos del templo, con 14 apariciones concentradas en las descripciones del templo de 1 Reyes 6 y especialmente Ezequiel 41. Son las pequeñas habitaciones construidas a lo largo de los muros exteriores del templo, apiladas en tres pisos y rodeando el santuario ''como costillas'' en torno a un cuerpo (1 R 6:5-8; Ez 41:5-11, 26). El español ''cámaras laterales'' y el alemán ''Seitenkammern'' crean compuestos que reflejan esta especialización.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130161, 'spa', 'Una costilla del cuerpo humano, con solo 2 apariciones, ambas en Génesis 2', 'Una costilla del cuerpo humano, con solo 2 apariciones, ambas en Génesis 2:21-22, donde Dios toma una de las costillas (o ''lados'') de Adán y construye con ella a una mujer. Es el uso más célebre de la palabra y posiblemente su núcleo etimológico. El español ''costilla'', el francés ''côte'' y el alemán ''Rippe'' emplean vocabulario anatómico específico para costilla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130166, 'spa', 'El costado del cuerpo de una persona, con 1 aparición en Job 18', 'El costado del cuerpo de una persona, con 1 aparición en Job 18:12, donde la calamidad está ''a su lado'' lista para golpear. Algunos leen ''tropiezo'' (de otra raíz), pero la lectura espacial ''en su flanco'' concuerda con el uso arquitectónico de la palabra. Esto tiende un puente entre los sentidos anatómico y espacial, aplicando la superficie lateral del cuerpo como marcador de proximidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130168, 'spa', 'Ladera o pendiente de un cerro, con 1 aparición en 2 Samuel 16', 'Ladera o pendiente de un cerro, con 1 aparición en 2 Samuel 16:13, donde Simei camina por la ladera (צֵלָע) opuesta a David, maldiciendo y arrojando piedras. La extensión geográfica de ''lado'' a ''cuesta o ladera de un cerro'' es natural, y BDB la glosa como ''costilla de cerro, es decir, cresta o terraza''. El español ''ladera'' y el alemán ''Hang'' seleccionan términos topográficos específicos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130169, 'spa', 'Nombre propio personal', 'Nombre personal, padre de uno de los constructores del muro en tiempos de Nehemías (Nehemías 3:30). El nombre posiblemente significa «alcaparra» según el uso del hebreo tardío. Aunque no se describe a Zalaf directamente, la participación de su hijo en la reconstrucción del muro identifica a la familia como repatriados comprometidos con la restauración de Jerusalén. La lista detallada de constructores preserva estos nombres como memorial de la fidelidad postexílica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130170, 'spa', 'Zelofejad (nombre personal)', 'Nombre personal de un hombre de la tribu de Manasés que murió sin hijos varones durante el período del desierto (Nm 26:33). Sus cinco hijas peticionaron a Moisés por derechos de herencia (Nm 27:1, 7) y Dios afirmó su reclamo, estableciendo un precedente en la ley israelita (Nm 36:2). El caso es uno de los ejemplos más notables en las Escrituras de innovación jurídica impulsada por la defensa de las mujeres.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130175, 'spa', 'Topónimo en Benjamín', 'Nombre de lugar en Benjamín mencionado en 1 Samuel 10:2, donde Samuel profetiza que Saúl encontrará a dos hombres cerca de la tumba de Raquel. La ubicación es incierta y los estudiosos sospechan corrupción textual, sugiriendo leer «desde Zelá» (cf. 2 Samuel 21:14). El nombre funciona como señal profética en la unción de Saúl.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130176, 'spa', 'Zumbido de insectos', 'Sonido vibrante o zumbido producido por las alas de insectos en vuelo. Isaías 18:1 habla de «la tierra del zumbido de alas», describiendo una región caracterizada por enjambres de insectos, posiblemente el alto Nilo con sus abundantes moscas. La palabra es onomatopéyica y evoca el murmullo incesante de innumerables alas batiendo rápidamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130177, 'spa', 'Arpón de pesca', 'Lanza o arpón diseñado para la caza de peces o criaturas marinas de gran tamaño. Job 40:31 (41:7) pregunta retóricamente si alguien puede llenar el cuero de Leviatán «con arpones», resaltando la futilidad de atacar a este monstruo con armas convencionales. El término deriva del sonido silbante que emite la lanza al ser lanzada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130178, 'spa', 'Langosta zumbadora', 'Tipo de langosta o grillo caracterizado por su zumbido o chirrido, mencionado en Deuteronomio 28:42 como maldición que «se apoderará de todos tus árboles y frutos». El nombre deriva del sonido distintivo que estos insectos producen en enjambres. Los cognados en lenguas semíticas emparentadas confirman esta identificación auditiva. Como maldición del pacto, representa la destrucción agrícola total.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130179, 'spa', 'címbalos litúrgicos', 'Los dos contextos son de celebración litúrgica: la procesión de David con el arca (2 Samuel 6:5) y el llamado comprehensivo a la alabanza en el Salmo 150. El salmo distingue entre ''címbalos de sonido/audición'' y ''címbalos de aclamación/resonancia'', posiblemente refiriéndose a diferentes tamaños o técnicas de ejecución. Todas las traducciones coinciden en el tipo de instrumento, con el español y el alemán notando la relación de constructo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130182, 'spa', 'Tener sed, sediento', 'Tener sed, experimentar sed, abarcando desde la deshidratación física literal hasta el anhelo espiritual intenso. El sentido literal predomina en contextos narrativos: Israel tiene sed en Refidim (Éx 17:3), Sansón tras derrotar a los filisteos (Jue 15:18), y trabajadores que prensan aceite de oliva pero permanecen sedientos (Job 24:11). En el uso profético y escatológico, se empareja con el hambre como imagen de la alianza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130190, 'spa', 'Sediento', 'Sediento, en estado de necesitar agua, aplicado a personas, tierras o terrenos. A menudo emparejado con ra''ev (''hambriento'') para expresar privación corporal, como en los hombres exhaustos de David (2 Sam 17:29), el trato justo al enemigo (Prov 25:21) y el vagar por el desierto (Sal 107:5). Isaías extiende la imagen figuradamente: los espiritualmente sedientos son invitados a aguas vivas (Isa 55:1), y la tierra seca recibe lluvia abundante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130196, 'spa', 'Sed (física)', 'Sed (física): la sensación corporal de necesitar agua, frecuentemente vinculada con el hambre (רָעָב) en listas de privación. Aparece en relatos del desierto (Éx 17:3; Jue 15:18), maldiciones del pacto (Dt 28:48) e imágenes de asedio (2 Cr 32:11). Los Salmos y los profetas la extienden figurativamente al duelo y al exilio (Is 41:17), y Amós 8:11 la orienta hacia el anhelo espiritual, pero el referente físico subyacente permanece constante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130207, 'spa', 'Sequedad de garganta', 'Condición reseca y agotada de la garganta a causa de la sed. Jeremías 2:25 la emplea figuradamente: Dios ordena a Israel descarriado que «guarde su garganta de la sequedad» (de correr tras otros dioses). La imagen física es vívida, una garganta llagada por el jadeo en persecución desesperada, aplicada al adulterio espiritual. Israel se agota persiguiendo falsos amantes, quedando reseca y desesperada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130208, 'spa', 'tierra árida', 'Aparecen tres usos teológicos distintos: prueba en el desierto (Deuteronomio), juicio divino que invierte la fertilidad (Salmo), y restauración escatológica (Isaías). El español usa consistentemente ''sedienta'' para la tierra, mientras algunas traducciones abstraen a la ''sed'' misma. La promesa de Isaías es la más dramática: la tierra misma que tiene sed se convertirá en manantiales—una inversión total. La imagen es vívida y poderosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130209, 'spa', 'Unirse, adherirse', 'Unirse o adherirse a algo o alguien, especialmente en devoción religiosa o lealtad. El Nifal reflexivo describe a Israel uniéndose a Baal Peor en culto idolátrico (Nm 25:3, 5; Sal 106:28). Las glosas multilingues reflejan el sentido de adhesión relacional (ing. ''joined'', esp. ''se unieron'', fra. ''joignit''), captando la decisión voluntaria pero funesta de uncirse a una deidad extranjera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130210, 'spa', 'Par, yunta (de animales)', 'Par, yunta (de animales): Un par, yunta o equipo de animales de tiro uncidos juntos, especialmente bueyes. En 1 Samuel 11:7 Saúl descuartiza una yunta de bueyes como llamado a las armas; Job 1:3 y 42:12 cuentan la riqueza en yuntas de bueyes; 1 Reyes 19:19 muestra a Eliseo arando con doce pares. La palabra también se aplica a pares de asnos (Jueces 19:3, 10), mulas (2 Reyes 5:17) y caballos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130217, 'spa', 'Yugada (medida de tierra)', 'Yugada (medida de tierra): Una yugada — medida de superficie agraria, originalmente definida como la extensión de terreno que una yunta de bueyes podía arar en un día. Isaías 5:10 es la única aparición: ''diez yugadas de viña producirán apenas un bato'', usando el plural constructo צִמְדֵּי. El término español ''yugada'' (derivado de ''yugo'') conserva hermosamente el vínculo etimológico con la imagen concreta de los animales uncidos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130219, 'spa', 'Velo femenino', 'Cantares 4:1, 4:3 y 6:7 emplean la frase «tus ojos tras tu velo» o «tus mejillas tras tu velo» (צַמָּתֵךְ), retratando la apariencia modesta pero cautivadora de la amada. Isaías 47:2 ordena a Babilonia «quitar tu velo» como primer paso de una serie de humillaciones. El término designa consistentemente una cobertura femenina asociada al recato y la dignidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130220, 'spa', 'Tortas de pasas', '1 Samuel 25:18 enumera «cien racimos de pasas» entre las ofrendas de paz de Abigail para David. 1 Samuel 30:12 menciona «dos racimos de pasas» para reanimar al egipcio. 2 Samuel 16:1 incluye «cien tortas de pasas» en las provisiones de Siba. 1 Crónicas 12:40 señala que los vecinos trajeron «tortas de pasas» a la celebración de David. Era alimento práctico y apreciado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130221, 'spa', 'Sentido causativo del Hifil', 'Sentido causativo del Hifil: hacer brotar, producir, hacer crecer, con Dios, la tierra o un huerto como agente que trae la vegetación o la descendencia. Con 14 apariciones, este sentido se abre con Dios haciendo crecer ''todo árbol agradable a la vista'' en el Edén (Gn 2:9), continúa con la maldición de espinas y cardos (Gn 3:18) y reaparece en el discurso profético donde Dios promete ''haré brotar justicia y alabanza'' (Is 61:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130222, 'spa', 'Sentido intransitivo del Qal', 'Sentido intransitivo del Qal: brotar, germinar o crecer, dicho de plantas, vegetación, cabello o, figuradamente, de personas y cosas que surgen y prosperan. Con 15 apariciones es el significado base: antes de que arbusto alguno ''hubiera brotado'' en el Edén (Gn 2:5), las espigas del sueño del Faraón ''brotando'' de un tallo (Gn 41:6, 23), la vegetación que rebrota tras la plaga de langostas (Éx 10:5). El español ''brotar'', el francés ''germer'' y el alemán ''sprossen'' convergen en la imagen botánica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130229, 'spa', 'Sentido intensivo del Piel', 'Sentido intensivo del Piel: crecer o aumentar, enfatizando el proceso o la plenitud del crecimiento más que la germinación inicial. Con 4 apariciones, esta raíz relativamente infrecuente aparece cuando el cabello de Sansón vuelve a crecer después de ser cortado (Jue 16:22), cuando se dice a los embajadores humillados que se queden en Jericó ''hasta que les crezca la barba'' (2 S 10:5; 1 Cr 19:5) y en la alegoría de Ezequiel sobre Jerusalén creciendo ''como brote del campo'' (Ez 16:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130249, 'spa', 'Renuevo (título mesiánico)', 'El Renuevo — título mesiánico que designa al gobernante justo prometido del linaje de David. Jeremías 23:5 anuncia ''Levantaré a David un Renuevo justo'', y Zacarías 3:8 y 6:12 lo emplean prácticamente como nombre propio: ''mi siervo el Renuevo''. El español transita del minúsculo ''renuevo'' al mayúsculo ''el Retoño'', y el suajili ''Chipukizi'' marca igualmente la transición a título real. Isaías 4:2 lo vincula con la gloria futura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130250, 'spa', 'Vegetación, crecimiento', 'Crecimiento colectivo o vegetación de la tierra — plantas, cultivos y lo que el suelo produce. Se usa para la cubierta vegetal destruida en Sodoma (Gn 19:25), el crecimiento del campo con el que se compara a Jerusalén (Ez 16:7), y la tierra que produce su fruto como señal de bendición divina (Sal 65:10; Is 61:11). El árabe ''nabat'' (vegetación) y el español ''planta de'' confirman el sentido botánico genérico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130252, 'spa', 'Tallo, brote individual', 'Tallo o brote individual de grano, distinguido de la vegetación colectiva. Oseas 8:7 advierte que la semilla sembrada por Israel producirá un tallo sin grano — imagen profética de futilidad. El árabe ''ghalla'' (rendimiento de grano) y el español ''grano'' se enfocan en el producto esperado más que en la planta misma, resaltando la amarga ironía: el tallo existe pero no produce nada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130257, 'spa', 'Brazalete, pulsera', 'Un brazalete o pulsera, banda ornamental que se lleva en la muñeca o el brazo. La evidencia multilingüe es llamativamente uniforme — español ''brazaletes'', francés ''bracelets'', alemán ''Armreife'' — reflejando lo concreto y culturalmente universal de este objeto. La mayoría de las apariciones se hallan en Génesis 24 (vv. 22, 30, 47), donde el siervo de Abraham entrega a Rebeca brazaletes de oro como obsequios de compromiso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130261, 'spa', 'Tapa asegurada', 'Cubierta o tapa de un recipiente, específicamente una que se ata o sujeta firmemente. Números 19:15 legisla sobre la impureza por contacto con cadáveres: todo recipiente abierto sin tapa atada quedaba impuro. Solo los recipientes sellados estaban protegidos de la contaminación dentro de una tienda con un muerto. El detalle de la atadura es esencial: las tapas sueltas no ofrecían protección; debían estar bien amarradas para constituir una barrera ritual efectiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130264, 'spa', 'Marchitarse, resecarse', 'Secarse, marchitarse o resecarse, usado en Oseas 9:14 en una sombría oración sobre el juicio de Israel: «dales pechos resecos» incapaces de amamantar. El verbo describe glándulas mamarias que se secan y pierden su función vital. Junto con «vientre que aborta», crea una imagen de fracaso reproductivo total: hijos perdidos antes de nacer o muertos de hambre después. El marchitamiento físico simboliza la devastación nacional que Dios anuncia como castigo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130265, 'spa', 'Lana', 'Lana: el vellón de oveja utilizado como materia prima y textil acabado. Aparece en contextos legales que la distinguen del lino en la contaminación de vestiduras (Lv 13:47-59) y la ley de mezcla de tejidos (Dt 22:11), en contextos económicos como producto natural valioso (Os 2:7, 11; 2 R 3:4; Pr 31:13), y en un llamativo uso figurado para la blancura y la pureza — el pecado hecho blanco como la lana (Is 1:18) y los copos de nieve comparados con la lana (Sal 147:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130276, 'spa', 'Copa del árbol', 'La copa o follaje más alto de un árbol, usado exclusivamente en las alegorías proféticas de Ezequiel sobre cedros y árboles altos. En Ez 17:3, 22 la gran águila arranca la copa de un cedro, simbolizando la monarquía davídica. En Ez 31:3, 10, 14 la copa imponente representa el orgullo de Asiria y Egipto. El esp. ''copa'' y el ing. ''top'' convergen en la imagen de ramas superiores exuberantes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130277, 'spa', 'Destruir, aniquilar (Hifil)', 'Destruir, aniquilar (Hifil): Destruir o aniquilar (Hifil causativo): el sentido dominante, usado para cortar enemigos, naciones o a los malvados. David destruyó a quienes se levantaron contra él (2 Sam 22:41; Sal 18:40), el salmista pide a Dios que destruya a sus enemigos (Sal 54:5; 101:8), y los que están lejos de Dios ''perecen'' (Sal 73:27). Se trata de una destrucción total y decisiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130279, 'spa', 'Ser cortado, perecer, desaparecer (Nifal)', 'Ser cortado, perecer, desaparecer (Nifal): Ser cortado, perecer o desaparecer (Nifal pasivo): el sujeto es destruido o se desvanece. Los wadis secos ''desaparecen'' con el calor (Job 6:17), y Job dice que ''no fue destruido'' a pesar de la oscuridad (Job 23:17). El español ''desaparecer'' y ''fui destruido'' captan la disolución pasiva que implica esta conjugación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130283, 'spa', 'Destruir por completo, consumir (Piel)', 'Destruir por completo, consumir (Piel): Destruir por completo o consumir (Piel intensivo): una intensificación de la destrucción básica, enfatizando la exhaustividad o la fuerza abrumadora. El celo ''me ha consumido'' (Sal 119:139) y los terrores ''me han destruido'' (Sal 88:16). El Piel imprime una cualidad personal y existencial de ser abrumado hasta el punto de la aniquilación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130285, 'spa', 'Poner fin, silenciar (Qal)', 'Poner fin, silenciar (Qal): Poner fin o silenciar (Qal, conjugación básica): el significado raíz sin aumentar, de cortar o terminar. En Lam 3:53 los enemigos ''cortaron mi vida en la fosa'', haciéndose eco del cognado árabe ''guardar silencio''. Es un acto único y decisivo de poner fin.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130290, 'spa', 'Zin (región desértica)', 'El desierto de Zin, región desértica en el sur del Néguev que forma el límite meridional de Canaán y abarca Cadés-barnea. Casi todas las apariciones provienen de la fuente sacerdotal, ya sea en listas de fronteras (Núm 34:3-4; Jos 15:1, 3) o en narraciones de la estancia de Israel (Núm 13:21; 20:1; 33:36). La expresión repetida midbar-tsin (''desierto de Zin'') enmarca algunos de los eventos más trascendentales del peregrinaje.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130296, 'spa', 'Ganchos o garfios', 'Ganchos o garfios usados para capturar o arrastrar, presentes en la profecía de Amós 4:2 contra las mujeres ricas de Samaria. Dios declara que vendrán días en que «os sacarán con ganchos», usando metáforas de pesca para la deportación militar. Junto con otro término para anzuelos, la imagen evoca cautivos enganchados y arrastrados como peces fuera del agua. Los garfios con púas aseguran que no haya escape, una metáfora brutal del juicio inminente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130297, 'spa', 'Frescura, frío', 'Frescura o frío, específicamente en la expresión «frescor de nieve» (Proverbios 25:13). El versículo compara al mensajero fiel con «el frescor de la nieve en tiempo de siega», cuando el alivio es más necesario y apreciado. El frío de la nieve durante el arduo trabajo de la cosecha era algo raro y revitalizante. La imagen capta cómo un siervo leal trae renovación psicológica y práctica a sus señores, restaurando sus fuerzas agotadas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130298, 'spa', 'Escudo grande, pavés', 'Escudo grande, pavés: un escudo defensivo grande de cuerpo entero (צִנָּה), distinto del מָגֵן más pequeño y redondo. Empleado por la infantería pesada y los escuderos en batalla (1 S 17:7, 41; 1 Cr 12:9, 25; 2 Cr 14:7; 25:5), figuró en la armería de oro de Salomón (1 R 10:16; 2 Cr 9:15) y en la expresión militar fija ''מָגֵן y צִנָּה'' (Jer 46:3; Ez 23:24; 38:4; Sal 35:2). Usado figuradamente del favor protector de Dios (Sal 5:12; 91:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130311, 'spa', 'descenso físico', 'Aparecen dos contextos narrativos: el desmonte deliberado de Acsa (repetido en Josué y Jueces) y el golpe violento hacia abajo de la estaca de la tienda (Jueces 4:21). El primero involucra un descenso intencional desde un asno, marcando una petición formal; el segundo describe una penetración letal. La evidencia interlingüística muestra glosas tanto corteses (''desmontó'') como violentas (''descendió hacia''), reflejando el alcance semántico del verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130313, 'spa', 'Tocado de dignidad', 'Tocado de tela enrollada que significa dignidad, usado por el sumo sacerdote (Zac 3:5), la realeza (Is 62:3, ''turbante de realeza'') o mujeres adineradas (Is 3:23). Job 29:14 extiende la imagen metafóricamente: la justicia le servía de turbante. La glosa esp. ''diadema'' junto a ''turbante'' muestra cómo los traductores perciben tanto la cobertura funcional como su connotación de honor y rango.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130314, 'spa', 'Reseco, marchito', 'Reseco, marchito o endurecido por desecación, describiendo las espigas del sueño de Faraón (Génesis 41:23). Las siete espigas eran «delgadas y marchitas», abrasadas por el viento del este hasta quedar inservibles. La conexión aramea con «piedra» sugiere que se endurecieron como roca. En la interpretación del sueño, estas espigas simbolizaban siete años de hambruna que devastarían Egipto, grano tan reseco que no servía ni para comer ni para sembrar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130315, 'spa', 'Ciudad en Judá', 'Nombre de una ciudad en el distrito de la Sefela de Judá (Josué 15:37), posiblemente idéntica a la Zaanán de Miqueas 1:11. Ubicada en las tierras bajas, formaba parte del territorio occidental de Judá. La Septuaginta conserva el nombre con adaptaciones griegas. Su inclusión en las listas de fronteras la establece como parte de la herencia tribal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130316, 'spa', 'Caminar con humildad', 'Caminar humildemente o conducirse con modestia, tal como aparece en la tríada de exigencias divinas de Miqueas 6:8: «practicar la justicia, amar la misericordia y caminar humildemente con tu Dios». El infinitivo absoluto Hifil intensifica el significado: cultivar el andar humilde como práctica de vida. Va más allá de actos aislados de humildad; describe un modo de vivir sostenido, marcado por la modestia y la reverencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130317, 'spa', 'Humilde de carácter', 'Humilde o modesto en carácter, describiendo a quienes practican la sencillez. Proverbios 11:2 contrasta a «los humildes» (con quienes mora la sabiduría) con «los arrogantes» (que reciben deshonra). El adjetivo señala a quienes tienen una visión adecuada y modesta de sí mismos, sin pretensiones indebidas. Esta humildad crea espacio para la sabiduría: el corazón dócil y dispuesto a aprender.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130318, 'spa', 'Enrollar, ceñir', 'Levítico 16:4 prescribe que el sumo sacerdote «se envolverá la cabeza con (בְּ) el turbante de lino» durante el ritual del Día de la Expiación. Isaías 22:18 emplea una repetición enfática: «te enrollará apretadamente (צָנוֹף יִצְנָפְךָ צְנֵפָה)», envolviéndote como una pelota para arrojarte lejos. Isaías 62:3 presenta una lectura Ketiv relacionada con esta raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130319, 'spa', 'Envoltura o turbante', 'Enrollamiento, envoltura u objeto enrollado (posiblemente un turbante), que aparece en el oráculo de juicio contra Sebna en Isaías 22:18. El difícil pasaje contiene imágenes de envolver y arrojar: Dios «te enrollará como una bola y te lanzará a una tierra extensa». El sustantivo, derivado de la raíz «enrollar», puede referirse a la acción de enrollar o a algo enrollado. En ambos casos, la imagen transmite un violento contraste.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130320, 'spa', 'Vasija de almacenamiento', 'Vasija o jarra utilizada para almacenamiento, mencionada específicamente en Éxodo 16:33 para preservar una muestra de maná. Moisés instruye a Aarón: «Toma una vasija, pon en ella un gomer de maná y colócala ante el Señor para que se conserve para las generaciones». Este recipiente debía preservar el pan como testimonio permanente de la provisión divina en el desierto. La vasija se convirtió en un objeto conmemorativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130321, 'spa', 'Conductos de aceite', 'Tubos o conductos que transportan líquido, específicamente en la visión del candelabro de oro de Zacarías 4:12: ''los dos tubos de oro que vierten aceite dorado.'' Estos conductos conectan los olivos con la lámpara, asegurando un suministro continuo de aceite. Representan el medio por el cual el poder divino —el aceite como símbolo del Espíritu— fluye sin cesar para que Israel cumpla su misión de ser luz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130322, 'spa', 'Caminar, marchar (Qal)', 'Sentido básico en Qal de caminar, dar pasos o marchar por iniciativa propia. Ya sea describiendo el avance teofánico de Dios por el desierto (Jue 5:4; Sal 68:7), los portadores de David avanzando con cuidado con el arca (2 Sam 6:13), o un joven vagando cerca de la esquina de la adúltera (Prov 7:8), la palabra transmite una zancada medida y deliberada, no un andar casual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130324, 'spa', 'Hacer marchar, conducir (Hifil)', 'Sentido causativo en Hifil: obligar a alguien a marchar, conducirlo o escoltarlo en contra de su voluntad. Atestiguado únicamente en Job 18:14, donde Bildad declara que el impío es «llevado a marchar ante el rey de los espantos». Las traducciones en español, inglés e hindi coinciden en enfatizar la compulsión externa: no es un movimiento voluntario, sino una procesión forzada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130330, 'spa', 'Paso, zancada, pisada', 'Paso, zancada, pisada: Un paso, zancada o pisada (צַעַד), que denota el acto físico de adelantar un pie y, por extensión, la trayectoria de la vida de una persona bajo la soberanía divina. Los usos literales describen pisada firme en batalla (2 Sam 22:37) y el andar majestuoso de los animales (Prov 30:29). El sentido figurado predomina en la literatura sapiencial y profética, donde los pasos representan el camino de vida que Dios ordena y observa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130341, 'spa', 'Brazaletes ornamentales', 'Brazaletes o bandas decorativas para la parte superior del brazo, mencionados en Isaías 3:20 entre los artículos de lujo femeninos. Aunque algunos los interpretan como ''cadenillas para los tobillos'', la mejor lectura es la de adornos para el brazo, marcadores visibles de riqueza y posición social. Propuestas textuales sugieren también brazaletes reales en 2 Reyes 11:12, vinculándolos con la investidura monárquica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130342, 'spa', 'Encorvarse o volcar', 'Encorvarse o inclinar el cuerpo, ya sea bajo una carga (Is 51:14), con vigor físico (Is 63:1, aunque muchos enmiendan a ''marchando''), o en postura de degradación moral (Jer 2:20). En el Piel (Jer 48:12), la acción se extiende transitivamente a volcar vasijas, representando el juicio sobre Moab. ''Encorvado'' y ''trasegadores'' reflejan ambas vertientes semánticas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130343, 'spa', 'velo de mujer', 'Las dos narrativas del Génesis usan el velo de manera diferente: el velo de Rebeca señala la modestia nupcial apropiada, mientras que el velo de Tamar permite el engaño. En ambos casos, la cubierta transforma la presentación social de la mujer—una honorablemente, la otra con duplicidad. El artículo definido y las formas posesivas (''el velo'', ''su velo'', ''con un velo'') marcan momentos narrativos específicos de cubrirse o descubrirse. La prenda comunica significado social y relacional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130344, 'spa', 'El uso más frecuente', 'El uso más frecuente: marcar al hijo menor o más joven en comparaciones de orden de nacimiento. La hija menor de Lot (Gén 19:31-38), Jacob el gemelo menor (Gén 25:23) y el hijo menor de Josué (1 Re 16:34) portan este sentido. El español ''menor'' distingue consistentemente este significado comparativo familiar de la mera pequeñez. Funciona casi como un término de parentesco en contextos genealógicos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130346, 'spa', 'Sustantivo plural que se refiere colectivamente a los ''pequeños'' o dependientes ', 'Sustantivo plural que se refiere colectivamente a los ''pequeños'' o dependientes de una comunidad — niños, subordinados o los miembros indefensos de un grupo. Jeremías lo usa para las poblaciones vulnerables de naciones que enfrentan juicio (Jer 14:3; 49:20; 50:45). Las variaciones ketiv/qere en Jeremías 48:4 muestran la conciencia escribal de que este sentido colectivo se superpone con el topónimo Zoar, etimológicamente vinculado a la misma raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130348, 'spa', 'Se centra en el rango y el estatus más que en la edad', 'Se centra en el rango y el estatus más que en la edad: el más pequeño, el más insignificante, el menor. Saúl objeta que su tribu es la ''más pequeña'' de Israel (1 Sam 9:21), y Miqueas profetiza que Belén, ''demasiado pequeña'' entre los clanes de Judá, producirá un gobernante (Miq 5:2). El español ''pequeño/pequeña'' y el emparejamiento del salmista con ''despreciado'' (Sal 119:141) dejan claro que se trata de magnitud social, no cronológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130352, 'spa', 'Uso absoluto (no comparativo) que describe a alguien como simplemente joven en a', 'Uso absoluto (no comparativo) que describe a alguien como simplemente joven en años, sin referencia a hermanos ni al orden de nacimiento. Job 30:1 habla de los ''más jóvenes que yo'' que se burlan de él, y Elihú en Job 32:6 se abstiene porque es ''joven en días.'' El español ''joven'' aparece aquí en lugar del comparativo ''menor,'' confirmando un perfil semántico distinto: la juventud como etapa de la vida, no una posición familiar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130364, 'spa', 'Topónimo edomita', 'Nombre de un lugar asociado con la región de Edom (2 Reyes 8:21), donde el rey Joram combatió contra los edomitas durante su revuelta. La ubicación es incierta, probablemente cercana a la frontera de Edom. La Septuaginta sugiere una conexión con Seír. Joram ''pasó a Zair'' con sus tropas pero no logró sofocar la rebelión, a pesar de una salida nocturna del cerco enemigo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130365, 'spa', 'Juventud relativa', 'Juventud o condición de ser más joven, empleado en Génesis 43:33 para describir cómo los hermanos de José fueron sentados ''conforme a su primogenitura y conforme a su juventud'', del mayor al menor. La disposición precisa por edad dejó atónitos a los hermanos, pues aquel ''egipcio'' no debería conocer su orden de nacimiento. El sustantivo destaca la posición relativa en la jerarquía de edad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130366, 'spa', 'Trasladar campamento', 'El verbo describe la acción de viajar o desplazarse, especialmente en el contexto de levantar campamento o reubicar una morada. Isaías 33:20 lo emplea en construcción negada para prometer que la ''tienda de Sion no será trasladada'': permanecerá fija y segura, en contraste con la naturaleza transitoria de la vida nómada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130367, 'spa', 'Zoán (ciudad egipcia)', 'Zoán (Tanis) — nombre propio que identifica la importante ciudad egipcia del noreste del delta del Nilo que sirvió como capital real. El Salmo 78:12 y 43 la recuerdan como el «campo de Zoán» donde Dios realizó señales y prodigios durante el Éxodo. Isaías 19:11 y 13 se burlan de los príncipes de Zoán por su consejo insensato, e Isaías 30:4 la menciona junto a Hanes como destino de la desafortunada embajada de Judá a Egipto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130371, 'spa', 'lugar en Neftalí', 'Dos contextos anclan este lugar: fronteras territoriales (Josué) y escenario narrativo (Jueces). La variación Ketiv-Qere y el [K] entre corchetes en varias traducciones reflejan incertidumbre textual sobre la forma precisa del nombre. El sitio se recuerda principalmente por Jueces 4—Heber plantó su tienda allí, y la tienda de Jael se convirtió en la escena de la muerte de Sísara. La evidencia interlingüística muestra variaciones ortográficas menores pero consenso sobre la función como topónimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130372, 'spa', 'Figuras esculpidas', 'Se refiere a figuras talladas o esculpidas, describiendo específicamente la técnica artística empleada para crear los querubines del templo de Salomón (2 Cr 3:10). La expresión ''obra de imagen'' sugiere representaciones tridimensionales talladas, no simples relieves planos ni pinturas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130373, 'spa', 'Clamar en angustia, aflicción o apelación urgente — el sentido nuclear del Qal y', 'Clamar en angustia, aflicción o apelación urgente — el sentido nuclear del Qal y el Piel. La sangre de Abel ''clama'' desde la tierra (Gn 4:10), Esaú ''clamó con un gran y amargo grito'' (Gn 27:34), y los israelitas ''clamaron a Yahvé'' repetidamente bajo la opresión (Éx 14:10; Jue 3:9, 15; 4:3; 6:6). El clamor va dirigido casi siempre a alguien con poder para intervenir.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130376, 'spa', 'Ser convocado o reunido por proclamación — el sentido Nifal (pasivo/reflexivo) d', 'Ser convocado o reunido por proclamación — el sentido Nifal (pasivo/reflexivo) donde las personas son congregadas mediante una convocatoria pública. Los mensajeros de Gedeón hacen que Neftalí y Aser sean ''convocados'' (Jue 7:23-24), Galaad se congrega contra Amón (Jue 10:17) y Efraín es ''convocado'' en rebeldía (Jue 12:1). El sentido es colectivo y pasivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130392, 'spa', 'Una sola aparición en el Hifil donde Samuel ''convocó'' al pueblo ante Yahvé en Mi', 'Una sola aparición en el Hifil donde Samuel ''convocó'' al pueblo ante Yahvé en Mizpa (1 S 10:17). Este uso causativo activo — convocar una asamblea en lugar de ser convocado — se distingue tanto del grito de angustia como de la convocación pasiva, funcionando como una convocatoria formal por parte de una figura de autoridad. El español ''convocó'' capta el carácter deliberado y oficial del acto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130414, 'spa', 'Clamor, grito de angustia', 'Clamor, grito de angustia: un grito fuerte que expresa aflicción, angustia o indignación moral, típicamente dirigido hacia Dios o escuchado por Él como súplica de justicia o liberación. El ''clamor'' de Sodoma (Gn 18:21; 19:13) señala maldad que demanda juicio; el grito de Israel en Egipto (Éx 3:7, 9) provoca el rescate divino. El mismo sustantivo cubre tanto el dolor personal (Gn 27:34) como la protesta comunitaria (Neh 5:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130429, 'spa', 'Ser humillado o pequeño', 'Tres contextos revelan el alcance de la palabra: ignorancia personal de la humillación de los hijos (Job), promesa profética contra la insignificancia nacional (Jeremías), y los vulnerables ''pequeños'' entre el pueblo disperso (Zacarías). El verbo puede ser estativo (ser pequeño/insignificante) o incoativo (volverse pequeño, ser humillado). La evidencia interlingüística muestra tanto usos adjetivales (''pequeño'', ''los pequeños'') como verbales (''serán menospreciados'', ''son humillados'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130430, 'spa', 'Zoar (topónimo)', 'Zoar (tso''ar), ciudad al extremo sureste del mar Muerto, una de las cinco ciudades de la llanura llamada originalmente Bela (Gén 14:2, 8). Su nombre, que significa ''pequeña'' o ''insignificante'', deriva de la súplica de Lot de que era ''una pequeñita'' (Gén 19:20), y fue librada de la destrucción de Sodoma y Gomorra como lugar de refugio de Lot (Gén 19:22-23, 30). Aparece en la vista panorámica de Moisés desde el Nebo (Deut 34:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130436, 'spa', 'Piel contraída', 'Describe la piel que se encoge y se contrae firmemente sobre los huesos a causa de una emaciación severa. En Lamentaciones 4:8, este verbo retrata el estado físico espantoso de las víctimas del hambre durante el asedio de Jerusalén, con la piel tensa y reseca contra sus marcos esqueléticos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130437, 'spa', 'El participio sustantivado צֹפֶה usado como nombre que significa ''atalaya'' o ''ce', 'El participio sustantivado צֹפֶה usado como nombre que significa ''atalaya'' o ''centinela'': alguien apostado como vigía sobre muros, torres o alturas. Es el uso dominante (22 de 37 apariciones). El vigía en Guibeá avista las tropas filisteas dispersándose (1 S 14:16); el atalaya de David informa sobre los mensajeros de Absalón que se acercan (2 S 13:34; 18:24-27); la llegada de Jehú se observa desde la torre (2 R 9:17-20). Los profetas asumen este papel: Ezequiel es puesto como ''atalaya'' sobre Israel (Ez 3:17; 33:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130438, 'spa', 'En Job 15', 'En Job 15:22, Elifaz dice que el impío está ''destinado'' o ''señalado'' para la espada: las tinieblas lo acechan y la destrucción le está asignada. Las dos apariciones provienen de este versículo. El español ''destinado'' sugiere que el sentido ha pasado de la vigilancia activa a la fijación pasiva del destino, un desplazamiento semántico notable de ''ser observado'' a ''estar marcado para'' la destrucción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130440, 'spa', 'La raíz Piel (intensiva) que expresa una espera ansiosa y expectante', 'La raíz Piel (intensiva) que expresa una espera ansiosa y expectante: mirar con anticipación sostenida hacia algo esperado o temido. Elí está sentado junto al camino ''vigilando'' ansioso por noticias del Arca (1 S 4:13); el salmista vigila hacia Dios cada mañana (Sal 5:3); Jeremías dice a Aroer que se ponga junto al camino y ''vigile'' a los fugitivos (Jer 48:19); en Lamentaciones 4:17, los ojos desfallecen de vigilar en vano esperando auxilio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130441, 'spa', 'Formas finitas y participiales del Qal usadas verbalmente para significar ''vigil', 'Formas finitas y participiales del Qal usadas verbalmente para significar ''vigilar'' u ''observar'' sin el matiz profesional de centinela. En Mizpa se pide a Dios que ''vigile'' entre Jacob y Labán para asegurar el cumplimiento del pacto (Gn 31:49). Los ojos de Dios ''vigilan'' a las naciones (Sal 66:7); los ojos del SEÑOR ''observan'' al malo y al bueno (Pr 15:3); la mujer virtuosa ''vigila'' la marcha de su hogar (Pr 31:27).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130455, 'spa', 'En el Salmo 37', 'En el Salmo 37:32, ''el impío acecha (צֹפֶה) al justo y busca matarlo''. Se trata de vigilancia depredadora: espiar con intención hostil en vez de vigilia protectora. El español ''acecha'' y el alemán ''spähte'' captan el tono amenazante. La entrada de BDB glosa explícitamente: ''el impío espía al justo''. Se distingue tanto del centinela-atalaya como de la espera esperanzada, constituyendo una inversión siniestra de la observación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130465, 'spa', 'La forma activa del Piel que significa revestir o chapear una superficie de made', 'La forma activa del Piel que significa revestir o chapear una superficie de madera con metal: oro, bronce o plata. Es el término constructivo por excelencia para el tabernáculo (Éx 25-38) y el templo (1 R 6; 2 Cr 3-4). El español ''cubrirás'' y el francés ''recouvrir'' transmiten la acción de recubrir. También se extiende al engaste con piedras preciosas (2 Cr 3:6). El alemán ''überziehen'' (''revestir por encima'') capta la técnica con precisión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130473, 'spa', 'Participio pasivo del Pual que describe un objeto ya revestido o chapeado', 'Participio pasivo del Pual que describe un objeto ya revestido o chapeado. Éxodo 26:32 habla de columnas cubiertas de oro, y Proverbios 26:23 compara labios fervientes con un corazón malvado a un tiesto ''revestido'' de escoria de plata. La forma pasiva presupone la artesanía completada del sentido 1 y describe el estado resultante en vez de la acción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130475, 'spa', 'Uso distinto del Qal en Isaías 21', 'Uso distinto del Qal en Isaías 21:5 que significa extender o disponer, probablemente referido a tender una alfombra o tapete. La mayoría de los comentaristas modernos lo ven como un sentido separado (o incluso una raíz homófona) del Piel metalúrgico. El contexto de una escena de banquete apoya una acción doméstica más que un trabajo de metalurgia. El español ''pon'' (''coloca'') y el inglés ''spread'' lo confirman.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130480, 'spa', 'Sangre fluyente', 'Denota la sangre en su estado fluyente: el derramamiento o flujo de sangre producto de una muerte violenta. Ezequiel 32:6 emplea este término al profetizar el juicio contra Egipto, describiendo cómo la tierra quedará saturada con la sangre derramada de los caídos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130481, 'spa', 'Jefe edomita', 'Tres referencias genealógicas identifican a este jefe edomita, con variación ortográfica menor entre Génesis (Tsefo) y Crónicas (Tsefi). El nombre aparece en listas de descendientes de Esaú que llegaron a ser ''jefes'' o ''líderes'' en Edom—la estructura tribal de la nación hermana de Israel. El alemán y el francés ponen entre corchetes la variante ''[צפי]'', notando la diferencia textual. El nombre puede derivar de una raíz que significa ''observar'' o ''mirar''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130482, 'spa', 'Revestimiento metálico', 'Chapado metálico aplicado a superficies de objetos cultuales: la cubierta de oro o plata de los capiteles del tabernáculo (Éx 38:17, 19), las planchas de bronce martilladas de los incensarios de Coré para el altar (Nm 16:38-39), y la cobertura de plata de los ídolos que Israel debe arrancar y desechar (Is 30:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130483, 'spa', 'Nombre personal', 'Nombre propio de uno de los hijos de Gad que se convirtió en fundador de un clan. Números 26:15 lo incluye en el censo del desierto, donde sus descendientes son contados como grupo familiar distintivo dentro de la asignación tribal de Gad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130484, 'spa', 'norte, punto cardinal', 'El punto cardinal norte como referencia geográfica y espacial para orientación, descripción de límites y posicionamiento. Aparece con he directivo (צָפוֹנָה, ''hacia el norte''), en cadenas constructas (מִצְּפוֹן לְ, ''al norte de'') y como coordenada junto a sur, este y oeste (Gn 13:14; 28:14). Las visiones del templo de Ezequiel dependen fuertemente de este sentido direccional, que abarca 120 de las 153 ocurrencias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130486, 'spa', 'norte amenazante', 'El norte como dirección amenazante y ominosa desde la cual se aproximan invasores y el juicio divino — 28 ocurrencias concentradas en el corpus profético, especialmente Jeremías y Ezequiel. ''Del norte se desatará el mal'' (Jer 1:14) establece el patrón; oráculos subsiguientes identifican a Babilonia y otras potencias descendiendo desde el norte como agentes de la ira de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130489, 'spa', 'Safón, montaña sagrada', 'El monte Safón como nombre propio o semi-propio — la montaña mitológica de los dioses en la religión cananea (ugarítico Sapanu), identificada con Jebel al-Aqra en la costa siria — en aproximadamente 5 ocurrencias. El Salmo 48:3 transfiere audazmente el título al monte Sion: ''hermoso en su elevación, gozo de toda la tierra, las alturas de Safón''. Isaías 14:13 sitúa el trono divino en los confines de Safón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130503, 'spa', 'Topónimo gadita', 'Nombre geográfico de una ciudad asignada a Gad al este del Jordán. Josué 13:27 la incluye en la descripción de los límites de la herencia de Gad, situándola en la parte norte de su territorio, cerca del río Jaboc.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130504, 'spa', 'Invasor del norte', 'Designa una fuerza destructiva proveniente del norte, identificada en Joel 2:20 donde Dios promete alejar «al norteño». Aunque las langostas no suelen llegar desde el norte, el término enfatiza el carácter extranjero y amenazante de la plaga, o bien describe metafóricamente a ejércitos invasores.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130505, 'spa', 'Clan sefonita', 'Designación colectiva para los miembros del clan sefonita, descendientes de Sefón, hijo de Gad. Números 26:15 usa este término en el contexto del censo para identificar a este grupo familiar con fines de herencia y organización tribal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130507, 'spa', 'Ave, pájaro pequeño o gorrión como término general que abarca los tres dominios ', 'Ave, pájaro pequeño o gorrión como término general que abarca los tres dominios principales: el rito de purificación levítico, la imaginería proverbial de libertad y vulnerabilidad, y el uso colectivo genérico. Esta acepción unificada representa el significado básico del sustantivo, del cual se especializan los demás sentidos según el contexto de uso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130526, 'spa', 'Zipor (nombre propio)', 'Zipor — nombre propio que significa «pájaro, gorrión» e identifica al padre de Balac, rey de Moab. Cada aparición (Núm 22:2, 4, 10, 16; 23:18; Jos 24:9; Jue 11:25) se presenta en la fórmula patronímica «Balac hijo de Zipor», estableciendo el linaje real de Balac en el contexto del intento moabita de hacer maldecir a Israel por medio de Balaam.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130527, 'spa', 'Jarra, vasija, frasco', 'Jarra, frasco o cántaro pequeño — recipiente portátil de forma aplanada o ancha, usado para transportar agua o aceite. En 1 Samuel 26:11, 12 y 16, es la vasija de agua que David tomó de junto a la cabecera de Saúl dormido en el desierto de Zif, demostrando que rehusó dañar al ungido del Señor. En 1 Reyes 17:12, 14 y 16, es la vasija de aceite de la viuda que se mantuvo milagrosamente durante la hambruna.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130530, 'spa', 'Vigilia o atalaya', 'Denota un lugar de vigilia o la actividad de mantener guardia, usado en Lamentaciones 4:17 para describir la desesperada espera de Jerusalén por ayuda militar. El contexto sugiere tanto una atalaya desde la que observaban como el prolongado período de vigilancia que resultó inútil cuando el aliado esperado no acudió.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130531, 'spa', 'Nombre propio', 'Nombre personal de un hijo de Gad, idéntico a Sefón pero con grafía diferente. Génesis 46:16 usa esta forma en la lista de los miembros de la familia de Jacob que emigraron a Egipto, donde este hijo habría nacido o viajado con su padre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130532, 'spa', 'Torta u oblea', 'Designa una torta fina y plana o una oblea, usada en Éxodo 16:31 como punto de comparación para describir la apariencia del maná. El símil sugiere que el maná se asemejaba a estas tortas delicadas y finas, ayudando a los israelitas a comprender la textura y forma de este alimento milagroso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130533, 'spa', 'Lugar elevado de observación', 'Nombre geográfico de un sitio elevado en o cerca del monte Pisga, adonde fue llevado Balaam para profetizar sobre Israel. Números 23:14 identifica este «campo de los vigías» como el escenario del segundo oráculo de Balaam, un punto alto con visión directa del campamento israelita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130534, 'spa', 'Tesoro acumulado', 'Se refiere a un tesoro o bienes almacenados de valor. En el Salmo 17:14 describe la riqueza terrenal que llena el vientre de aquellos cuya porción se limita a esta vida. El término enfatiza posesiones materiales que han sido acumuladas y guardadas como bienes preciados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130535, 'spa', 'Machos cabríos sacrificiales', 'Término arameo para machos cabríos, empleado en Esdras 6:17 en la lista de animales sacrificados en la dedicación del segundo templo. Estos machos cabríos sirvieron como ofrenda por el pecado, doce en total, en correspondencia con las doce tribus de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130536, 'spa', 'Macho cabrío', 'Un macho cabrío, utilizado tanto en contextos profético-simbólicos como en rituales sacrificiales. En Daniel 8, el tsaphir es el conspicuo macho cabrío venido del occidente, identificado explícitamente como el rey de Grecia (Dn 8:21), cuyo gran cuerno se quiebra y es reemplazado por cuatro. La expresión española ''macho cabrío'' subraya el género masculino del animal. En el ámbito cultual, el plural aparece en ofrendas por el pecado (2 Cr 29:21; Esd 8:35).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130540, 'spa', 'Corona o destino', 'El uso de Isaías es claro: una diadema o chaplet de belleza, parte de las imágenes reales y honoríficas (paralelo a ''corona de gloria''). Las dos instancias de Ezequiel son enigmáticas—no encajan contextualmente con ''mañana'', y ''destino'' (como fatalidad que viene en círculo) es plausible pero incierto. Algunos sugieren ''diadema'' incluso en Ezequiel 7:10, refiriéndose a la casa real. Las glosas multilingües muestran confusión (formas entre corchetes en alemán y francés).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130541, 'spa', 'Alfombra para banquete', 'Probablemente designa una alfombra o tapete tendido para comer, según Isaías 21:5, en la descripción de los líderes babilónicos preparando un festín. La expresión «tender la alfombra» sugiere disponer textiles para reclinarse durante la comida, formando parte de la imagen irónica de quienes festejan despreocupadamente antes del juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130542, 'spa', 'Ocultamiento activo de una persona u objeto para evitar su descubrimiento', 'Ocultamiento activo de una persona u objeto para evitar su descubrimiento. La madre de Moisés ''lo escondió'' tres meses (Éx 2:2); Rahab escondió a los espías (Jos 2:4). El español ''esconder'' y el francés ''cacher'' reflejan consistentemente el acto directo de ocultar. El sentido abarca ocultamiento protector y acción furtiva a lo largo de las formas del Qal (perfecto, imperfecto y participio).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130544, 'spa', 'Significado extendido de guardar algo valioso para uso futuro', 'Significado extendido de guardar algo valioso para uso futuro: atesorar los mandamientos de Dios (Pr 2:1; 7:1) o, en sentido negativo, acumular iniquidad para los hijos (Job 21:19). El español ''atesorar'' capta este matiz con precisión. Job 23:12 muestra al justo atesorando las palabras divinas más que el pan de cada día, vinculando el almacenamiento secreto con el compromiso devocional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130546, 'spa', 'Un giro siniestro', 'Un giro siniestro: ocultarse con intención hostil, acechar en emboscada. Proverbios 1:11 invita a ''embosquemos por sangre'', y el Salmo 10:8 describe al impío que ''acecha en lugares secretos''. El español ''emboscar'' y ''acechar'' subrayan la connotación depredadora que distingue este sentido del ocultamiento benigno.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130547, 'spa', 'Un matiz de amparo en el Salmo 31', 'Un matiz de amparo en el Salmo 31:20: ''Los ocultarás en el secreto de tu presencia''. El español ''los ocultarás'' y el inglés ''You shelter them'' sugieren un ocultamiento divino protector que va más allá de la mera ocultación, implicando refugio íntimo bajo el cuidado de Dios, una coloración singular dentro del campo semántico más amplio de esta raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130549, 'spa', 'Nifal pasivo', 'Nifal pasivo: el estado de estar oculto o escondido. Job 15:20 dice que la cantidad de años ''está oculta'' al opresor; Jeremías 16:17 insiste en que nada está escondido de los ojos de Dios. El español ''están escondidos'' y ''se ocultó'' confirman la orientación pasiva. Este sentido se centra en el estado resultante más que en la acción de ocultar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130553, 'spa', 'El participio pasivo del Qal funcionando como sustantivo', 'El participio pasivo del Qal funcionando como sustantivo: ''lo que está guardado'', es decir, tesoro o riqueza oculta. Proverbios 13:22 declara que la riqueza del pecador está ''guardada'' para el justo. El Salmo 17:14 habla de los ''protegidos'' de Dios, mientras que Ezequiel 7:22 se refiere a tesoros sagrados. Las traducciones al francés y al alemán distinguen este uso como léxicamente diferenciado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130558, 'spa', 'Hifil causativo', 'Hifil causativo: hacer que alguien quede oculto, a menudo con intención protectora. Job 14:13 suplica ''¡escóndeme en el Seol!'' como refugio, y el Salmo 56:6 (ketiv) puede reflejar una lectura causativa similar. El sentido conlleva matices de resguardar a una persona del peligro mediante ocultamiento deliberado por parte de un agente más poderoso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130574, 'spa', 'Sofonías (nombre propio)', 'Sofonías (tsephanyah/tsephanyahu), nombre teofórico que significa ''YHWH ha escondido/atesorado'', portado por al menos cuatro figuras del AT. El profeta Sofonías es autor del libro que lleva su nombre durante el reinado de Josías (Sof 1:1), predicando sobre el Día de YHWH. El sacerdote Sofonías hijo de Maasías sirvió como intermediario clave entre el establecimiento del templo de Jerusalén y Jeremías (Jer 21:1; 29:25, 29; 37:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130578, 'spa', 'Nombre egipcio de José', 'Nombre de trono egipcio otorgado a José por el faraón al elevarlo a visir de Egipto. Génesis 41:45 registra esta designación como parte de la investidura oficial de José, marcando su transformación de prisionero hebreo a alto funcionario egipcio con un nombre real que significa aproximadamente «Dios habla y él vive».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130579, 'spa', 'Víbora venenosa', 'Designa una serpiente venenosa o víbora, empleada metafóricamente en Isaías 14:29 para representar un peligro político creciente. El profeta advierte a Filistea que de su opresor caído surgirá una amenaza aún más letal, simbolizada por esta víbora, ilustrando cómo los peligros pueden intensificarse.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130580, 'spa', 'Víbora venenosa', 'Proverbios 23:32 advierte que el vino «al final muerde como serpiente y pica como víbora» (כְּצִפְעֹנִי). Isaías 11:8 vislumbra al niño de pecho jugando sin temor sobre la cueva de la víbora en la creación restaurada. Isaías 59:5 acusa a los malvados de incubar «huevos de víbora», es decir, planes mortíferos. Jeremías 8:17 amenaza con «serpientes, víboras» (צִפְעֹנִים) imposibles de encantar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130581, 'spa', 'Retoños familiares', 'Se refiere a los descendientes o ramificaciones de una familia, usando la imagen botánica de brotes que surgen de una planta. Isaías 22:24 emplea este término junto a «descendencia» para describir a todos los familiares de Eliaquim que dependerán de él, tanto hijos directos como parientes más lejanos, como ramas de un árbol genealógico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130582, 'spa', 'Gorjear, susurrar', 'Isaías 8:19 describe a médiums y adivinos «que gorjean y murmuran» (הַמְצַפְצְפִים וְהַמַּהְגִּים). Isaías 10:14 dice que nadie «abrió la boca ni emitió un piar» en señal de resistencia. Isaías 38:14 presenta a Ezequías gimiendo: «como golondrina o grulla gorjeo» (אֲצַפְצֵף). Isaías 29:4 promete que la voz de Jerusalén «susurrará desde el polvo» (תְּצַפְצֵף) como un fantasma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130583, 'spa', 'Sauce', 'Designa un tipo de sauce, empleado en Ezequiel 17:5 dentro de una alegoría sobre siembra y crecimiento. El profeta describe la plantación «como un sauce», un árbol que por naturaleza prospera junto al agua, utilizando esta imagen en la alegoría mayor sobre la relación de Sedequías con Babilonia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130584, 'spa', 'Partir temprano', 'Significa marcharse o partir, posiblemente con el matiz de hacerlo al amanecer. Jueces 7:3 emplea este verbo en la orden divina de dejar ir a los temerosos del ejército de Gedeón, lo que resultó en la partida de 22.000 de los 32.000 reunidos, quedando solo 10.000 antes de que Dios redujera aún más la tropa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130585, 'spa', 'Aves del cielo', 'Daniel 4:12 (arameo 4:9) describe a las aves morando entre las ramas del árbol. Daniel 4:14 (4:11) ordena «que las aves huyan de sus ramas». Daniel 4:21 (4:18) repite que «las aves del cielo» habitaban en sus ramas. Daniel 4:33 (4:30) posiblemente alude a las aves (o rasgos aviares) durante el estado bestial del rey.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130586, 'spa', 'Rana (la criatura de la plaga)', 'Rana (la criatura de la plaga): El anfibio enviado como plaga sobre Egipto, que apareció en masa desde el Nilo para invadir casas, camas y hornos. Usado colectivamente en singular (Éx 8:2; Sal 78:45) y en plural (Éx 7:27–8:9; Sal 105:30). El uso restringido — confinado enteramente al relato de la plaga del Éxodo y sus evocaciones salmísticas — confiere a la palabra una carga teológica que va mucho más allá de su referente zoológico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130591, 'spa', 'Esposa de Moisés', 'Tres momentos narrativos definen a Séfora: su matrimonio con Moisés (Éxodo 2:21), su dramática circuncisión de su hijo (4:25), y su regreso de una separación temporal (18:2). Ella actúa decisivamente en el capítulo 4, realizando la circuncisión que aparentemente apacigua la ira de Dios contra Moisés. Las traducciones interlingüísticas son consistentes (Zipporah, Séphora, Zippora, Tsiporah), tratando esto como un simple nombre propio sin variación semántica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130593, 'spa', 'Ciudad cananea', 'Nombre de una ciudad cananea conquistada por Judá y Simeón y posteriormente renombrada Horma. Jueces 1:17 relata cómo, tras derrotar esta ciudad, la consagraron a la destrucción total y le dieron un nuevo nombre que reflejaba su destino, estableciéndola como posesión israelita en la región del Néguev.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130594, 'spa', 'Capitel de columna', 'Designa el capitel o remate superior de una columna, mencionado en 2 Crónicas 3:15 en referencia a los dos grandes pilares que se erguían frente al templo de Salomón. Estos capiteles probablemente estaban chapados en metal y servían como elementos decorativos que coronaban las imponentes columnas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130595, 'spa', 'Valle de Sefata', 'Nombre geográfico de un valle cercano a Maresa donde Asá enfrentó la masiva invasión etíope. 2 Crónicas 14:10 identifica este valle como el lugar de la batalla en que el rey de Judá clamó al Señor y fue testigo de una intervención divina que puso en fuga a un ejército de un millón de hombres.');